-- Preserve control-plane identities while allowing audited state projections.
CREATE TRIGGER runs_identity_guard BEFORE UPDATE OF run_id,mode,created_at ON runs WHEN NEW.run_id IS NOT OLD.run_id OR NEW.mode IS NOT OLD.mode OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER runs_delete_guard BEFORE DELETE ON runs BEGIN SELECT RAISE(ABORT,'accounting identities cannot be deleted'); END;
CREATE TRIGGER runs_replace_guard BEFORE INSERT ON runs WHEN EXISTS(SELECT 1 FROM runs WHERE run_id=NEW.run_id) BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER reservations_identity_guard BEFORE UPDATE OF reservation_id,run_id,action_id,amount_micro_usd,provider,account,limits_json,created_at ON reservations WHEN NEW.reservation_id IS NOT OLD.reservation_id OR NEW.run_id IS NOT OLD.run_id OR NEW.action_id IS NOT OLD.action_id OR NEW.amount_micro_usd IS NOT OLD.amount_micro_usd OR NEW.provider IS NOT OLD.provider OR NEW.account IS NOT OLD.account OR NEW.limits_json IS NOT OLD.limits_json OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER reservations_delete_guard BEFORE DELETE ON reservations BEGIN SELECT RAISE(ABORT,'accounting identities cannot be deleted'); END;
CREATE TRIGGER reservations_replace_guard BEFORE INSERT ON reservations WHEN EXISTS(SELECT 1 FROM reservations WHERE reservation_id=NEW.reservation_id) OR EXISTS(SELECT 1 FROM reservations WHERE run_id=NEW.run_id AND action_id=NEW.action_id) BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER payments_identity_guard BEFORE UPDATE OF provider,account,mode,payment_id,run_id,job_id ON payments WHEN NEW.provider IS NOT OLD.provider OR NEW.account IS NOT OLD.account OR NEW.mode IS NOT OLD.mode OR NEW.payment_id IS NOT OLD.payment_id OR NEW.run_id IS NOT OLD.run_id OR NEW.job_id IS NOT OLD.job_id BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER payments_delete_guard BEFORE DELETE ON payments BEGIN SELECT RAISE(ABORT,'accounting identities cannot be deleted'); END;
CREATE TRIGGER payments_replace_guard BEFORE INSERT ON payments WHEN EXISTS(SELECT 1 FROM payments WHERE provider=NEW.provider AND account=NEW.account AND mode=NEW.mode AND payment_id=NEW.payment_id) BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER checkouts_identity_guard BEFORE UPDATE OF provider,account,mode,request_id,run_id,job_id,amount_micro_usd,details,fingerprint,created_at ON checkouts WHEN NEW.provider IS NOT OLD.provider OR NEW.account IS NOT OLD.account OR NEW.mode IS NOT OLD.mode OR NEW.request_id IS NOT OLD.request_id OR NEW.run_id IS NOT OLD.run_id OR NEW.job_id IS NOT OLD.job_id OR NEW.amount_micro_usd IS NOT OLD.amount_micro_usd OR NEW.details IS NOT OLD.details OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER checkouts_delete_guard BEFORE DELETE ON checkouts BEGIN SELECT RAISE(ABORT,'accounting identities cannot be deleted'); END;
CREATE TRIGGER checkouts_replace_guard BEFORE INSERT ON checkouts WHEN EXISTS(SELECT 1 FROM checkouts WHERE provider=NEW.provider AND account=NEW.account AND mode=NEW.mode AND request_id=NEW.request_id) BEGIN SELECT RAISE(ABORT,'immutable accounting authorization'); END;
CREATE TRIGGER payments_numeric_insert BEFORE INSERT ON payments WHEN typeof(NEW.released_micro_usd)!='integer' OR NEW.released_micro_usd<0 OR typeof(NEW.pending_liability_micro_usd)!='integer' OR NEW.pending_liability_micro_usd<0 OR typeof(NEW.revision)!='integer' OR NEW.revision<0 BEGIN SELECT RAISE(ABORT,'invalid accounting projection'); END;
CREATE TRIGGER payments_numeric_update BEFORE UPDATE ON payments WHEN typeof(NEW.released_micro_usd)!='integer' OR NEW.released_micro_usd<0 OR typeof(NEW.pending_liability_micro_usd)!='integer' OR NEW.pending_liability_micro_usd<0 OR typeof(NEW.revision)!='integer' OR NEW.revision<0 BEGIN SELECT RAISE(ABORT,'invalid accounting projection'); END;
CREATE TRIGGER reservations_numeric_insert BEFORE INSERT ON reservations WHEN typeof(NEW.provisional_micro_usd)!='integer' OR NEW.provisional_micro_usd<0 OR (NEW.actual_micro_usd IS NOT NULL AND (typeof(NEW.actual_micro_usd)!='integer' OR NEW.actual_micro_usd<0)) BEGIN SELECT RAISE(ABORT,'invalid accounting projection'); END;
CREATE TRIGGER reservations_numeric_update BEFORE UPDATE ON reservations WHEN typeof(NEW.provisional_micro_usd)!='integer' OR NEW.provisional_micro_usd<0 OR (NEW.actual_micro_usd IS NOT NULL AND (typeof(NEW.actual_micro_usd)!='integer' OR NEW.actual_micro_usd<0)) BEGIN SELECT RAISE(ABORT,'invalid accounting projection'); END;
CREATE TRIGGER checkout_binding_guard BEFORE UPDATE OF payment_id,url ON checkouts WHEN (OLD.payment_id IS NOT NULL AND NEW.payment_id IS NOT OLD.payment_id) OR (OLD.url IS NOT NULL AND NEW.url IS NOT OLD.url) BEGIN SELECT RAISE(ABORT,'immutable checkout binding'); END;
